namespace sv_007e998dba894ca699df222b5b8c1bdd.Services;

/// <summary>
/// Scoped service (per-circuit in Blazor Server) that holds the currently
/// selected warehouse and notifies all subscribed components when it changes.
/// Each user circuit gets its own independent instance.
/// </summary>
public sealed class WarehouseStateService
{
    public static readonly IReadOnlyList<(string Id, string Name)> AvailableWarehouses =
    [
        ("WH-A", "Warehouse A"),
        ("WH-B", "Warehouse B"),
        ("WH-C", "Warehouse C"),
        ("WH-D", "Warehouse D"),
    ];

    private string _currentWarehouseId = AvailableWarehouses[0].Id;

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        AvailableWarehouses.First(w => w.Id == _currentWarehouseId).Name;

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId)
            return;

        _currentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_007e998dba894ca699df222b5b8c1bdd.Services;

/// <summary>
/// Scoped service that provides low-stock alert counts and notifies all
/// subscribed components when new data arrives.  Polling is driven by the
/// consumer (Dashboard page) so it only runs while that page is visible.
/// </summary>
public sealed class InventoryAlertService
{
    private readonly Random _random = new();

    private int _lastCount;

    /// <summary>Most recently fetched low-stock count.</summary>
    public int CurrentCount => _lastCount;

    /// <summary>Raised after <see cref="RefreshAsync"/> completes so every
    /// subscriber (sidebar badge, dashboard, etc.) can re-render.</summary>
    public event Action? OnAlertCountChanged;

    /// <summary>Simulates a database query returning a random 0-15 count.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate latency + random result
        int count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Fetches the latest count for the given warehouse, stores it, and
    /// raises <see cref="OnAlertCountChanged"/> so all listeners update.
    /// </summary>
    public async Task RefreshAsync(string warehouseId)
    {
        _lastCount = await GetLowStockCountAsync(warehouseId);
        OnAlertCountChanged?.Invoke();
    }
}

