@page "/dashboard"
@using sv_007e998dba894ca699df222b5b8c1bdd.Services
@rendermode InteractiveServer
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard - @WarehouseState.CurrentWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mt-4">
    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Current Warehouse</h5>
                <p class="card-text fs-4">
                    <strong>@WarehouseState.CurrentWarehouseName</strong>
                    <span class="text-muted small">(@WarehouseState.CurrentWarehouseId)</span>
                </p>
            </div>
        </div>
    </div>

    <div class="col-md-6">
        <div class="card @(AlertService.CurrentCount > 5 ? "border-danger" : "border-success")">
            <div class="card-body">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="card-text fs-1">
                    @if (AlertService.CurrentCount > 5)
                    {
                        <span class="text-danger">⚠ @AlertService.CurrentCount items</span>
                    }
                    else
                    {
                        <span class="text-success">@AlertService.CurrentCount items</span>
                    }
                </p>
                <p class="text-muted small">
                    Polling every 10 seconds &bull; Last refresh: @_lastRefresh.ToString("HH:mm:ss")
                </p>
            </div>
        </div>
    </div>
</div>

@code {
    private CancellationTokenSource? _cts;
    private DateTime _lastRefresh = DateTime.Now;

    protected override async Task OnInitializedAsync()
    {
        WarehouseState.OnChange += OnWarehouseChanged;
        AlertService.OnAlertCountChanged += OnAlertCountChanged;

        // Initial fetch + start polling
        await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
        _lastRefresh = DateTime.Now;

        _cts = new CancellationTokenSource();
        _ = PollAsync(_cts.Token);
    }

    private async Task PollAsync(CancellationToken ct)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        try
        {
            while (await timer.WaitForNextTickAsync(ct))
            {
                await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
                _lastRefresh = DateTime.Now;
                await InvokeAsync(StateHasChanged);
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on dispose
        }
    }

    private async void OnWarehouseChanged()
    {
        // Immediately refresh alerts for the newly selected warehouse
        await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
        _lastRefresh = DateTime.Now;
        await InvokeAsync(StateHasChanged);
    }

    private void OnAlertCountChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        WarehouseState.OnChange -= OnWarehouseChanged;
        AlertService.OnAlertCountChanged -= OnAlertCountChanged;
    }
}

